  .bl-hours-row.bl-today .bl-hours-time { color: var(--bl-accent-dark); font-weight: 700; }
  .bl-hours-badge {
    display: inline-block;
    margin-left: 8px;
    padding: 1px 8px;
    border-radius: 999px;
