  (function () {
    try {
      var form = document.getElementById('bl-order-form');
      var totalEl = document.getElementById('bl-order-total');
      var msgEl = document.getElementById('bl-order-msg');
      var nameEl = document.getElementById('bl-order-customer');
      if (!form || !totalEl) { return; }
      var inputs = form.querySelectorAll('.bl-order-qty');
      var PHONE = '919845000000';

      function qtyOf(input) {
        var n = parseInt(input.value, 10);
        if (isNaN(n) || n < 0) { n = 0; }
        if (n > 20) { n = 20; }
        return n;
      }

      function lines() {
        var out = [];
        for (var i = 0; i < inputs.length; i++) {
          var q = qtyOf(inputs[i]);
          if (q > 0) {
            var price = parseInt(inputs[i].getAttribute('data-price'), 10);
            out.push({ name: inputs[i].getAttribute('data-name'), qty: q, price: price, sub: q * price });
          }
        }
        return out;
      }

      function total(items) {
        var t = 0;
        for (var i = 0; i < items.length; i++) { t += items[i].sub; }
        return t;
      }

      function update() {
        totalEl.textContent = '\u20B9' + total(lines());
        if (msgEl) { msgEl.textContent = ''; }
      }

      for (var i = 0; i < inputs.length; i++) {
        inputs[i].addEventListener('input', update);
        inputs[i].addEventListener('change', function () {
          // normalise out-of-range or blank values after editing
          this.value = String(qtyOf(this));
          update();
        });
      }

      form.addEventListener('submit', function (e) {
        e.preventDefault();
        var items = lines();
        if (items.length === 0) {
          if (msgEl) { msgEl.textContent = 'Please choose at least one item.'; }
          return;
        }
        var text = 'Hi Brew Lab, I would like to pre-order for pickup:\n';
        for (var j = 0; j < items.length; j++) {
          text += '- ' + items[j].qty + ' x ' + items[j].name + ' (\u20B9' + items[j].sub + ')\n';
        }
        text += 'Total: \u20B9' + total(items) + '\n';
        var who = nameEl ? nameEl.value.replace(/^\s+|\s+$/g, '') : '';
        if (who) { text += 'Name: ' + who + '\n'; }
        text += 'Pay at pickup.';
        var url = 'https://wa.me/' + PHONE + '?text=' + encodeURIComponent(text);
        var w = null;
        try { w = window.open(url, '_blank'); } catch (err) { w = null; }
        if (!w) { window.location.href = url; }
      });

      update();
    } catch (err) {
      /* never break the rest of the page */
    }
  })();
